{
  "name": "@argabor/caveman-opencode-plugin",
  "version": "0.2.0",
  "description": "Caveman communication mode plugin for opencode (V1 and V2)",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": ["dist"],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/argabor/caveman-opencode-plugin.git"
  },
  "homepage": "https://github.com/argabor/caveman-opencode-plugin#readme",
  "scripts": {
    "build": "bun run build.ts && tsc --emitDeclarationOnly",
    "dev": "opencode plugin dev",
    "setup": "bun run src/setup.ts",
    "test": "bun test",
    "test:watch": "bun test --watch"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.32",
    "@types/node": "25.6.0",
    "typescript": "6.0.3"
  },
  "keywords": ["opencode", "plugin", "caveman"],
  "author": "renux918",
  "license": "MIT"
}
